:5,"comment":"We had a wonderful and relaxing stay.. Mahal ang presyo kumpara sa serbisyo.","photo_url":"","created_at":"2022-07-20T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2022-07-18"},{"id":"past-fb-B1000","guest_name":"Walk-in","guest_email":"past-b1000@imported.elenest.local","booking_id":"past-B1000","stars":3,"comment":"Standard na resort para sa presyo. and May ilang sira sa banyo.","photo_url":"","created_at":"2022-07-20T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2022-07-18"}]$elenest_hist$::jsonb) as x(
  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

-- feedback 5/6
insert into public.guest_feedback (
  id, guest_name, guest_email, booking_id, stars, comment, photo_url,
  created_at, sentiment_archived, sentiment_week_key
)
select
  x.id, x.guest_name, x.guest_email, x.booking_id, x.stars, x.comment, x.photo_url,
