3,"comment":"Medyo madumi yung area nung dumating kami.. In addition, Panalo ang view, seryoso.","photo_url":"","created_at":"2023-04-07T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2023-04-03"},{"id":"past-fb-B1500","guest_name":"Carlo Domingo","guest_email":"past-b1500@imported.elenest.local","booking_id":"past-B1500","stars":5,"comment":"Not bad for a short trip.. Also, Highly recommended itong resort na ito.","photo_url":"","created_at":"2023-04-08T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2023-04-03"}]$elenest_hist$::jsonb) as x(
  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

commit;
